import json, os
import matplotlib.pyplot as plt
from matplotlib.patches import PathPatch, Rectangle
from matplotlib.path import Path

with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)['energy_sankey']

nodes = data['nodes']
flows = data['flows']
unit = data['unit']

id_to_node = {n['id']: n for n in nodes}

primary_order = ['oil','coal','natural_gas','nuclear','hydro','wind','solar','biomass','geothermal']
trans_order = ['thermal_power','refining','direct_use','electricity_grid']
end_order = ['transport','industry','buildings','agriculture','other','waste_heat']

stage_nodes = {
    'primary': primary_order,
    'transformation': trans_order,
    'end_use': end_order
}

node_color = {
    'oil':'#3b2f2f','coal':'#4b4b4b','natural_gas':'#6d6a75','nuclear':'#7b5ea7','hydro':'#2c7fb8',
    'wind':'#4eb3d3','solar':'#f2c14e','biomass':'#6aa84f','geothermal':'#a05a2c','thermal_power':'#8a8f99',
    'refining':'#6b5b53','direct_use':'#7a8b5b','electricity_grid':'#3f6ea8','transport':'#1f77b4',
    'industry':'#2ca02c','buildings':'#9467bd','agriculture':'#8c564b','other':'#7f7f7f','waste_heat':'#e4572e'
}

fossil = {'oil','coal','natural_gas'}
renew = {'hydro','wind','solar','biomass','geothermal'}

def link_color(s,t):
    if t=='waste_heat':
        return (228/255,87/255,46/255,0.78)
    if s in fossil:
        return (70/255,70/255,70/255,0.45)
    if s in renew:
        return (76/255,175/255,80/255,0.45)
    if s in {'thermal_power','refining'}:
        return (90/255,90/255,90/255,0.40)
    return (70/255,110/255,168/255,0.35)

# Build incoming/outgoing lookup
outgoing = {n['id']: [] for n in nodes}
incoming = {n['id']: [] for n in nodes}
for f in flows:
    outgoing[f['source']].append(f)
    incoming[f['target']].append(f)

for k in outgoing: outgoing[k].sort(key=lambda x: x['target'])
for k in incoming: incoming[k].sort(key=lambda x: x['source'])

# Stage totals and scaling
stage_totals = {}
for stage, ids in stage_nodes.items():
    stage_totals[stage] = sum(max(sum(x['value'] for x in outgoing[i]), sum(x['value'] for x in incoming[i])) for i in ids)

max_total = max(stage_totals.values())
canvas_y0, canvas_y1 = 0.08, 0.92
usable_h = canvas_y1-canvas_y0

gap_frac = {'primary':0.012,'transformation':0.02,'end_use':0.014}

# compute node vertical extents
node_pos = {}
for stage, ids in stage_nodes.items():
    gaps = gap_frac[stage]*(len(ids)-1)
    scale = (usable_h - gaps) / stage_totals[stage]
    y = canvas_y1
    for nid in ids:
        val = max(sum(x['value'] for x in outgoing[nid]), sum(x['value'] for x in incoming[nid]))
        h = val*scale
        node_pos[nid] = {'y1':y, 'y0':y-h, 'h':h, 'scale':scale}
        y = y-h-gap_frac[stage]

x_stage = {'primary':0.08, 'transformation':0.50, 'end_use':0.92}
node_w = 0.018

# allocate flow slots
source_cursor = {nid: node_pos[nid]['y0'] for nid in node_pos}
target_cursor = {nid: node_pos[nid]['y0'] for nid in node_pos}

flow_geom = []
for f in flows:
    s,t,v = f['source'],f['target'],f['value']
    hs = v*node_pos[s]['scale']
    ht = v*node_pos[t]['scale']
    y0s = source_cursor[s]; y1s = y0s+hs; source_cursor[s]=y1s
    y0t = target_cursor[t]; y1t = y0t+ht; target_cursor[t]=y1t
    flow_geom.append((s,t,v,y0s,y1s,y0t,y1t))

fig, ax = plt.subplots(figsize=(18,10), dpi=140)
ax.set_xlim(0,1); ax.set_ylim(0,1); ax.axis('off')
fig.patch.set_facecolor('white'); ax.set_facecolor('white')

def draw_band(x0,x1,ya0,ya1,yb0,yb1,color):
    c = 0.32*(x1-x0)
    verts = [
        (x0, ya0),
        (x0+c, ya0),
        (x1-c, yb0),
        (x1, yb0),
        (x1, yb1),
        (x1-c, yb1),
        (x0+c, ya1),
        (x0, ya1),
        (x0, ya0)
    ]
    codes = [Path.MOVETO,Path.CURVE4,Path.CURVE4,Path.CURVE4,Path.LINETO,Path.CURVE4,Path.CURVE4,Path.CURVE4,Path.CLOSEPOLY]
    patch = PathPatch(Path(verts,codes), facecolor=color, edgecolor=(0,0,0,0.12), lw=0.3)
    ax.add_patch(patch)

for s,t,v,y0s,y1s,y0t,y1t in sorted(flow_geom, key=lambda x: x[2]):
    x0 = x_stage[id_to_node[s]['stage']]+node_w
    x1 = x_stage[id_to_node[t]['stage']]
    draw_band(x0,x1,y0s,y1s,y0t,y1t,link_color(s,t))

for nid, pos in node_pos.items():
    x = x_stage[id_to_node[nid]['stage']]
    rect = Rectangle((x,pos['y0']), node_w, pos['h'], facecolor=node_color[nid], edgecolor=(0,0,0,0.4), lw=0.5)
    ax.add_patch(rect)
    label = id_to_node[nid]['label']
    if id_to_node[nid]['stage']=='primary':
        ax.text(x-0.008, (pos['y0']+pos['y1'])/2, label, ha='right', va='center', fontsize=10.5, color='#1f2937')
    elif id_to_node[nid]['stage']=='transformation':
        ax.text(x+node_w/2, pos['y1']+0.006, label, ha='center', va='bottom', fontsize=10.2, color='#1f2937')
    else:
        ax.text(x+node_w+0.008, (pos['y0']+pos['y1'])/2, label, ha='left', va='center', fontsize=10.5, color='#1f2937')

ax.text(0.5, 0.975, 'Global Energy Flows by Source, Transformation, and End Use (2022)', ha='center', va='top', fontsize=21, color='#111827', weight='bold')
ax.text(0.5, 0.948, f'Flow width is proportional to energy volume ({unit})', ha='center', va='top', fontsize=12.5, color='#374151')

ax.text(0.09, 0.925, 'Primary Energy Sources', ha='left', va='bottom', fontsize=12, color='#111827', weight='bold')
ax.text(0.50, 0.925, 'Transformation Processes', ha='center', va='bottom', fontsize=12, color='#111827', weight='bold')
ax.text(0.92, 0.925, 'End-Use Sectors', ha='right', va='bottom', fontsize=12, color='#111827', weight='bold')

lx, ly = 0.22, 0.02
legend_items = [
    ('Waste / Rejected Heat flows (highlighted)', (228/255,87/255,46/255,0.78)),
    ('Fossil-fuel-origin flows', (70/255,70/255,70/255,0.45)),
    ('Renewable-origin flows', (76/255,175/255,80/255,0.45)),
]
for i,(txt,col) in enumerate(legend_items):
    x = lx + i*0.27
    ax.add_patch(Rectangle((x,ly),0.02,0.015,facecolor=col,edgecolor='none'))
    ax.text(x+0.024, ly+0.0075, txt, va='center', ha='left', fontsize=10.5, color='#374151')

os.makedirs('/app/output', exist_ok=True)
plt.savefig('/app/output/result.png', dpi=160, bbox_inches='tight')
print('saved /app/output/result.png')
