    'refining':'#6b5b53','direct_use':'#7a8b5b','electricity_grid':'#3f6ea8','transport':'#1f77b4',
    'industry':'#2ca02c','buildings':'#9467bd','agriculture':'#8c564b','other':'#7f7f7f','waste_heat':'#e4572e'
}

fossil = {'oil','coal','natural_gas'}
renew = {'hydro','wind','solar','biomass','geothermal'}

def rgba(hex_color, a=255):
    h = hex_color.lstrip('#')
    return (int(h[0:2],16), int(h[2:4],16), int(h[4:6],16), a)

