    if t=='waste_heat': return (228,87,46,200)
    if s in fossil: return (70,70,70,120)
    if s in renew: return (76,175,80,120)
    if s in {'thermal_power','refining'}: return (90,90,90,110)
    return (70,110,168,95)

outgoing = {n['id']:[] for n in nodes}; incoming = {n['id']:[] for n in nodes}
for f in flows:
    outgoing[f['source']].append(f); incoming[f['target']].append(f)
for k in outgoing: outgoing[k].sort(key=lambda x:x['target'])
for k in incoming: incoming[k].sort(key=lambda x:x['source'])

stage_totals = {}
for stage, ids in stage_nodes.items():
    stage_totals[stage] = sum(max(sum(x['value'] for x in outgoing[i]), sum(x['value'] for x in incoming[i])) for i in ids)

W,H = 2200,1300
img = Image.new('RGBA',(W,H),'white')
draw = ImageDraw.Draw(img,'RGBA')

try:
    title_font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',48)
    subtitle_font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',28)
    label_font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',23)
    small_font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',20)
    bold_font = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',24)
except:
    title_font = subtitle_font = label_font = small_font = bold_font = ImageFont.load_default()

left, right = 160, W-180
top, bottom = 160, H-190
usable_h = bottom-top

gap_frac = {'primary':0.012,'transformation':0.02,'end_use':0.014}
node_pos = {}
for stage, ids in stage_nodes.items():
    gaps = gap_frac[stage]*(len(ids)-1)
    scale = (usable_h - gaps*usable_h) / stage_totals[stage]
    y = top
    for nid in ids:
        val = max(sum(x['value'] for x in outgoing[nid]), sum(x['value'] for x in incoming[nid]))
        h = val*scale
        node_pos[nid] = {'y0':y,'y1':y+h,'h':h,'scale':scale}
        y = y+h+gap_frac[stage]*usable_h

x_stage = {'primary':220,'transformation':1080,'end_use':1880}
node_w = 28

source_cursor = {nid: node_pos[nid]['y0'] for nid in node_pos}
target_cursor = {nid: node_pos[nid]['y0'] for nid in node_pos}
flow_geom = []
for f in flows:
    s,t,v = f['source'],f['target'],f['value']
    hs = v*node_pos[s]['scale']; ht = v*node_pos[t]['scale']
    y0s=source_cursor[s]; y1s=y0s+hs; source_cursor[s]=y1s
    y0t=target_cursor[t]; y1t=y0t+ht; target_cursor[t]=y1t
    flow_geom.append((s,t,v,y0s,y1s,y0t,y1t))

# Draw smooth ribbons as many thin polygons
for s,t,v,y0s,y1s,y0t,y1t in sorted(flow_geom,key=lambda x:x[2]):
    x0 = x_stage[id_to_node[s]['stage']] + node_w
    x1 = x_stage[id_to_node[t]['stage']]
    c = (x1-x0)*0.35
    steps = 36
    top_pts=[]; bot_pts=[]
    for i in range(steps+1):
        u=i/steps
        # cubic bezier interpolation for x,y
        x = (1-u)**3*x0 + 3*(1-u)**2*u*(x0+c) + 3*(1-u)*u**2*(x1-c) + u**3*x1
        yt = (1-u)**3*y0s + 3*(1-u)**2*u*y0s + 3*(1-u)*u**2*y0t + u**3*y0t
        yb = (1-u)**3*y1s + 3*(1-u)**2*u*y1s + 3*(1-u)*u**2*y1t + u**3*y1t
        top_pts.append((x,yt)); bot_pts.append((x,yb))
    poly = top_pts + bot_pts[::-1]
    draw.polygon(poly, fill=link_color(s,t), outline=(0,0,0,20))

# Nodes and labels
for nid,pos in node_pos.items():
    x = x_stage[id_to_node[nid]['stage']]
    draw.rectangle([x,pos['y0'],x+node_w,pos['y1']], fill=rgba(node_color[nid]), outline=(40,40,40,120), width=1)
    label = id_to_node[nid]['label']
    cy = (pos['y0']+pos['y1'])/2
    if id_to_node[nid]['stage']=='primary':
        tw = draw.textbbox((0,0),label,font=label_font)[2]
        draw.text((x-14-tw, cy-11), label, fill=(31,41,55,255), font=label_font)
    elif id_to_node[nid]['stage']=='transformation':
        tw = draw.textbbox((0,0),label,font=small_font)[2]
        draw.text((x+node_w//2-tw/2, pos['y0']-28), label, fill=(31,41,55,255), font=small_font)
    else:
        draw.text((x+node_w+12, cy-11), label, fill=(31,41,55,255), font=label_font)

# Title/subtitles
title = 'Global Energy Flows by Source, Transformation, and End Use (2022)'
sub = f'Flow band width is proportional to energy volume ({unit})'
tw = draw.textbbox((0,0),title,font=title_font)[2]
draw.text(((W-tw)/2,24), title, fill=(17,24,39,255), font=title_font)
sw = draw.textbbox((0,0),sub,font=subtitle_font)[2]
draw.text(((W-sw)/2,86), sub, fill=(55,65,81,255), font=subtitle_font)

# Stage headers
for txt,x in [('Primary Energy Sources',220),('Transformation Processes',1080),('End-Use Sectors',1880)]:
    bw = draw.textbbox((0,0),txt,font=bold_font)[2]
    draw.text((x+node_w/2-bw/2,125), txt, fill=(17,24,39,255), font=bold_font)

# Legend
legend_y = H-95
items=[('Waste / Rejected Heat flows (highlighted)',(228,87,46,200)),('Fossil-fuel-origin flows',(70,70,70,120)),('Renewable-origin flows',(76,175,80,120))]
x=420
for txt,col in items:
    draw.rectangle([x,legend_y,x+34,legend_y+22], fill=col)
    draw.text((x+44,legend_y-1),txt,fill=(55,65,81,255),font=small_font)
    x += 560

# axis-like note
draw.text((65,H-45), f'Units: {unit} (Exajoules)', fill=(55,65,81,255), font=small_font)

os.makedirs('/app/output', exist_ok=True)
img.convert('RGB').save('/app/output/result.png', 'PNG')
print('saved /app/output/result.png')
